begin;
set local search_path=public,extensions;
select plan(11);

select ok((select count(*)=5 and bool_and(p.prosecdef and p.proconfig @> array['search_path=pg_catalog']) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname like 'complete_catalog_%_version_identity'),'all replacement functions remain SECURITY DEFINER with fixed pg_catalog search_path');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname like 'complete_catalog_%_version_identity' and (has_function_privilege('anon',p.oid,'EXECUTE') or has_function_privilege('authenticated',p.oid,'EXECUTE') or has_function_privilege('service_role',p.oid,'EXECUTE'))),'all replacement functions remain inaccessible to API runtime roles');



select is((select code||':'||slug from public.catalog_library_versions where id='e2870000-0000-0000-0000-000000000001'),'HISTORIC_LIB:historic-lib','explicit historical library code and slug are preserved');
select is((select code||':'||slug from public.catalog_category_versions where id='e2880000-0000-0000-0000-000000000001'),'HISTORIC_CAT:historic-category','explicit historical category code and slug are preserved');
select is((select category_id::text||':'||code||':'||slug from public.catalog_subcategory_versions where id='e2890000-0000-0000-0000-000000000001'),'e2830000-0000-0000-0000-000000000001:HISTORIC_SUB:historic-subcategory','explicit historical subcategory parent, code and slug are preserved');
select is((select primary_subcategory_id::text||':'||code||':'||slug from public.catalog_service_versions where id='e28a0000-0000-0000-0000-000000000001'),'e2840000-0000-0000-0000-000000000002:HISTORIC_SERVICE:historic-service','explicit historical service parent, code and slug are preserved');
select is((select service_id::text||':'||subcategory_id::text||':'||link_type from public.catalog_service_subcategory_link_versions where id='e28b0000-0000-0000-0000-000000000001'),'e2850000-0000-0000-0000-000000000002:e2840000-0000-0000-0000-000000000002:SECONDARY','explicit historical link endpoints and type are preserved');

select throws_ok($$insert into public.catalog_category_versions(id,category_id,library_id,version,name_fr,name_ar,description_fr,description_ar,sort_order,change_reason,content_hash,created_by) values ('e2880000-0000-0000-0000-000000000009','e2830000-0000-0000-0000-000000000002','e2820000-0000-0000-0000-000000000002',9,'Identité croisée','هوية متقاطعة','Doit être refusée','يجب رفضها',9,'Identité bibliothèque invalide',repeat('9',64),'e2800000-0000-0000-0000-000000000001')$$,'23514','CATALOG_CATEGORY_VERSION_IDENTITY_MISMATCH','cross-library identity remains fail-closed');
select throws_ok($$insert into public.catalog_library_versions(id,library_id,version,name_fr,name_ar,description_fr,description_ar,icon_key,sort_order,change_reason,content_hash,created_by) values ('e2870000-0000-0000-0000-000000000009','e2820000-0000-0000-0000-000000000099',9,'Identité absente','هوية مفقودة','Doit être refusée','يجب رفضها','shield',9,'Identité absente invalide',repeat('8',64),'e2800000-0000-0000-0000-000000000001')$$,'23514','CATALOG_LIBRARY_VERSION_IDENTITY_MISMATCH','absent identity remains fail-closed');
select throws_ok($$insert into public.catalog_service_versions(id,service_id,library_id,version,primary_subcategory_id,name_fr,name_ar,short_description_fr,short_description_ar,long_description_fr,long_description_ar,service_type,unit_label_fr,unit_label_ar,sort_order,change_reason,content_hash,created_by) values ('e28a0000-0000-0000-0000-000000000009','e2850000-0000-0000-0000-000000000001','e2820000-0000-0000-0000-000000000001',9,'e2840000-0000-0000-0000-000000000003','Parent croisé','أصل متقاطع','Doit échouer','يجب أن يفشل','Parent bibliothèque étrangère','أصل مكتبة أجنبية','CONSULTING','jour','يوم',9,'Parent bibliothèque invalide',repeat('7',64),'e2800000-0000-0000-0000-000000000001')$$,'23514','CATALOG_SERVICE_VERSION_PARENT_MISMATCH','explicit cross-library parent remains fail-closed');
select lives_ok($$insert into public.catalog_category_versions(id,category_id,library_id,version,name_fr,name_ar,description_fr,description_ar,sort_order,change_reason,content_hash,created_by) values ('e2880000-0000-0000-0000-000000000002','e2830000-0000-0000-0000-000000000002','e2820000-0000-0000-0000-000000000001',2,'Writer historique','كاتب قديم','Colonnes snapshot omises','تم حذف أعمدة اللقطة',2,'Compatibilité ancien writer',repeat('6',64),'e2800000-0000-0000-0000-000000000001')$$,'omitted snapshot fields are still completed for an older writer');

select * from finish();
rollback;
